#!/usr/bin/env python3
"""
open_drift_ticket.py
====================
Called by CI when brain-contract-check fails. Opens a Linear issue in the
appropriate team with the conformance report, PR context, and the specific
invariants that drifted.

Team routing logic:
  - OSE drift -> OSE team
  - Brain schema issues (detected by failure type) -> OCR-doc team
  - Unknown -> OUR team

Auth: requires LINEAR_API_KEY in env. Key must have write access to the
relevant teams.

Idempotency: if a ticket already exists for this PR+commit combination
(detected via a tag in the description), update it instead of creating
a duplicate.
"""
import argparse, json, os, sys, urllib.request, urllib.error

LINEAR_API = 'https://api.linear.app/graphql'

# Team keys defined in the brain / Linear workspace. In practice these should
# be pulled from the brain's product-registry.yaml -> products.*.linear_team
# once that field is added. Hardcoded here for now.
TEAM_ROUTING = {
    'ose': 'OSE',
    'oureventring': 'OSE',
    'osm': 'OSE',
    'wkrp': 'OCR',
    'oaw': 'OCR',
    'osg': 'OCR',
    'osr': 'OCR',
    'osp': 'OCR',
    'brain': 'OCR-doc',
    'unknown': 'OCR',
}

# These failure check names indicate a brain-level problem (not a product
# problem), so the ticket should go to OCR-doc team instead
BRAIN_LEVEL_FAILURES = {
    'faith_commitment',       # brain missing faith_organization override
    'uec_codes_in_sync',      # could be either, defaults to product team
}


def graphql(query: str, variables: dict, api_key: str) -> dict:
    body = json.dumps({'query': query, 'variables': variables}).encode()
    req = urllib.request.Request(
        LINEAR_API,
        data=body,
        headers={
            'Content-Type': 'application/json',
            'Authorization': api_key,
        },
        method='POST',
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        print(f'HTTP {e.code}: {e.read().decode()}', file=sys.stderr)
        raise


def get_team_id(team_key: str, api_key: str) -> str:
    q = '''
    query($key: String!) {
      teams(filter: {key: {eq: $key}}) {
        nodes { id key name }
      }
    }
    '''
    data = graphql(q, {'key': team_key}, api_key)
    nodes = data.get('data', {}).get('teams', {}).get('nodes', [])
    if not nodes:
        raise RuntimeError(f'team {team_key} not found in Linear workspace')
    return nodes[0]['id']


def search_existing_issue(team_id: str, search_tag: str, api_key: str) -> str | None:
    """Find an existing issue in the team whose description contains the idempotency tag."""
    q = '''
    query($teamId: String!, $query: String!) {
      issues(
        filter: {team: {id: {eq: $teamId}}, description: {contains: $query}}
        first: 5
      ) {
        nodes { id identifier title }
      }
    }
    '''
    try:
        data = graphql(q, {'teamId': team_id, 'query': search_tag}, api_key)
        nodes = data.get('data', {}).get('issues', {}).get('nodes', [])
        return nodes[0]['id'] if nodes else None
    except Exception:
        return None


def build_description(report: dict, repo: str, pr_number: str, pr_url: str,
                      pr_author: str, commit: str, search_tag: str) -> str:
    failures = report.get('failures', [])
    passes = report.get('passes', [])
    summary = report.get('summary', {})

    failure_list = '\n'.join(
        f'- **`{f["check"]}`** — {f["detail"]}' for f in failures
    )
    pass_list = '\n'.join(f'- `{p["check"]}`' for p in passes[:5])
    if len(passes) > 5:
        pass_list += f'\n- ... and {len(passes) - 5} more'

    return f'''## Brain contract drift detected

The CI `brain-contract-check` workflow failed. The product repo drifted from the OCR-docs governance brain.

### Context
- **Repo:** `{repo}`
- **PR:** [#{pr_number}]({pr_url})
- **Author:** @{pr_author}
- **Commit:** `{commit[:8]}`
- **Product:** `{report.get("product_id", "unknown")}`

### Summary
- Failures: **{summary.get("failed", len(failures))}**
- Passes: {summary.get("passed", len(passes))}
- Total checks: {summary.get("total", len(failures) + len(passes))}

### Failures

{failure_list or "_none recorded_"}

### Passes

{pass_list or "_none recorded_"}

### Resolution path

1. If the product code is correct: open a PR against `ourCommunityRituals/OCR-docs` to update the brain contract, then re-run this workflow.
2. If the brain is correct: update the product code to match and push. The workflow will re-run and close this ticket if the new commit conforms.
3. If both are wrong: propose the correct shape in a comment on this ticket before committing anything.

---
_Auto-generated by `open_drift_ticket.py`. Idempotency tag: `{search_tag}`._
'''


def create_or_update_ticket(team_key: str, title: str, description: str,
                             search_tag: str, api_key: str) -> str:
    team_id = get_team_id(team_key, api_key)
    existing_id = search_existing_issue(team_id, search_tag, api_key)

    if existing_id:
        q = '''
        mutation($id: String!, $description: String!) {
          issueUpdate(id: $id, input: {description: $description}) {
            success issue { id identifier url }
          }
        }
        '''
        data = graphql(q, {'id': existing_id, 'description': description}, api_key)
        issue = data.get('data', {}).get('issueUpdate', {}).get('issue', {})
        print(f'Updated existing Linear issue: {issue.get("identifier")} {issue.get("url")}')
        return issue.get('url', '')

    q = '''
    mutation($teamId: String!, $title: String!, $description: String!) {
      issueCreate(input: {
        teamId: $teamId
        title: $title
        description: $description
      }) {
        success issue { id identifier url }
      }
    }
    '''
    data = graphql(q, {'teamId': team_id, 'title': title, 'description': description}, api_key)
    issue = data.get('data', {}).get('issueCreate', {}).get('issue', {})
    if not issue:
        raise RuntimeError(f'Linear issue creation failed: {data}')
    print(f'Created Linear issue: {issue.get("identifier")} {issue.get("url")}')
    return issue.get('url', '')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--report', required=True)
    ap.add_argument('--repo', required=True)
    ap.add_argument('--pr-number', required=True)
    ap.add_argument('--pr-url', required=True)
    ap.add_argument('--pr-author', required=True)
    ap.add_argument('--commit', required=True)
    args = ap.parse_args()

    api_key = os.environ.get('LINEAR_API_KEY')
    if not api_key:
        print('LINEAR_API_KEY not set; skipping ticket creation', file=sys.stderr)
        sys.exit(0)

    try:
        report = json.loads(open(args.report).read())
    except Exception as e:
        print(f'could not read report: {e}', file=sys.stderr)
        sys.exit(1)

    failures = report.get('failures', [])
    if not failures:
        print('no failures to report')
        sys.exit(0)

    # Route by product_id + failure type
    product_id = report.get('product_id', 'unknown')
    has_brain_failure = any(f['check'] in BRAIN_LEVEL_FAILURES for f in failures)
    team_key = 'OCR-doc' if has_brain_failure else TEAM_ROUTING.get(product_id, 'OUR')

    # Idempotency: one ticket per (product, PR, commit) triple
    search_tag = f'drift:{product_id}:pr-{args.pr_number}:{args.commit[:8]}'
    title = f'[brain-drift] {product_id} drift on PR #{args.pr_number}'
    description = build_description(
        report=report, repo=args.repo, pr_number=args.pr_number,
        pr_url=args.pr_url, pr_author=args.pr_author, commit=args.commit,
        search_tag=search_tag,
    )

    url = create_or_update_ticket(team_key, title, description, search_tag, api_key)

    gh_out = os.environ.get('GITHUB_OUTPUT')
    if gh_out:
        with open(gh_out, 'a') as f:
            f.write(f'ticket_url={url}\n')


if __name__ == '__main__':
    main()
